package blockbranch.client.realistic;
import java.nio.file.*;import blockbranch.realistic.CoastalMatchedProbe;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.minecraft.client.gui.screens.TitleScreen;
public final class CoastalMatchedClient {static boolean open;static long deadline;public static void register(){deadline=System.nanoTime()+1800_000_000_000L;ClientTickEvents.END_CLIENT_TICK.register(c->{if(System.nanoTime()>deadline||CoastalMatchedProbe.failure!=null){try{Files.writeString(Path.of(System.getProperty("blockbranch.coastalMatchedDir")).resolve("client-failure.txt"),"timeout or failure "+CoastalMatchedProbe.phase+" "+CoastalMatchedProbe.failure);}catch(Exception e){}c.stop();return;}if(!open&&c.gui.screen() instanceof TitleScreen){open=true;c.createWorldOpenFlows().openWorld("Compare",()->c.gui.setScreen(new TitleScreen()));return;}if(c.player==null||c.level==null)return;int chunks=0;var p=c.player.chunkPosition();for(int z=p.z()-2;z<=p.z()+2;z++)for(int x=p.x()-2;x<=p.x()+2;x++)if(c.level.getChunkSource().hasChunk(x,z))chunks++;CoastalMatchedProbe.ready=chunks==25&&Math.abs(c.player.getX()-CoastalMatchedProbe.tx)<.1&&Math.abs(c.player.getZ()-CoastalMatchedProbe.tz)<.1;if(CoastalMatchedProbe.done)c.stop();});}}
